-- Fresh PostgreSQL schema for Render. Does not import existing Cloudflare D1 data.
CREATE TABLE "customers" (
	"phone" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"updates_opt_in" integer DEFAULT 1 NOT NULL,
	"offers_opt_in" integer DEFAULT 0 NOT NULL,
	"orders_count" integer DEFAULT 0 NOT NULL,
	"last_order_at" text DEFAULT '' NOT NULL,
	"updated_at" text DEFAULT '' NOT NULL
, "account_type" text DEFAULT 'retail' NOT NULL, "business_name" text DEFAULT '' NOT NULL);

CREATE TABLE "notifications" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
	"order_id" text,
	"phone" text NOT NULL,
	"name" text DEFAULT '' NOT NULL,
	"kind" text NOT NULL,
	"message" text NOT NULL,
	"summary" text DEFAULT '' NOT NULL,
	"status" text NOT NULL,
	"error" text,
	"wa_message_id" text,
	"created_at" text NOT NULL,
	"sent_at" text,
	"sent_by" text
);

CREATE TABLE "order_events" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
	"order_id" text NOT NULL,
	"status" text NOT NULL,
	"action" text NOT NULL,
	"actor" text NOT NULL,
	"note" text,
	"created_at" text NOT NULL
);

CREATE TABLE "orders" (
	"id" text PRIMARY KEY NOT NULL,
	"owner" text NOT NULL,
	"request_key" text NOT NULL,
	"payload" text NOT NULL,
	"created_at" text NOT NULL
, "status" text DEFAULT 'placed' NOT NULL, "slot" text DEFAULT '' NOT NULL, "total" integer DEFAULT 0 NOT NULL, "assignee" text, "packed" text DEFAULT '[]' NOT NULL, "cash_collected" integer, "updated_at" text DEFAULT '' NOT NULL);

CREATE TABLE "payment_intents" (
	"id" text PRIMARY KEY NOT NULL,
	"owner" text NOT NULL,
	"request_key" text NOT NULL,
	"payload" text NOT NULL,
	"amount" integer NOT NULL,
	"razorpay_order_id" text NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"payment_id" text,
	"created_at" text NOT NULL,
	"expires_at" text NOT NULL,
	"inventory_released" integer DEFAULT 0 NOT NULL,
	"notifications_sent" integer DEFAULT 0 NOT NULL
);

CREATE TABLE "payment_stock_holds" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
	"payment_intent_id" text NOT NULL,
	"product_id" text NOT NULL,
	"quantity" integer NOT NULL,
	"released_at" text
);

CREATE TABLE "products" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"local" text DEFAULT '' NOT NULL,
	"unit" text NOT NULL,
	"price" integer NOT NULL,
	"mrp" integer NOT NULL,
	"category" text NOT NULL,
	"image" text NOT NULL,
	"stock" integer DEFAULT 0 NOT NULL,
	"active" integer DEFAULT 1 NOT NULL,
	"sort" integer DEFAULT 0 NOT NULL,
	"updated_at" text DEFAULT '' NOT NULL, "needs_price_review" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "products_stock_non_negative" CHECK("products"."stock" >= 0),
	CONSTRAINT "products_price_positive" CHECK("products"."price" > 0)
);

CREATE TABLE "staff" (
	"email" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"phone" text DEFAULT '' NOT NULL,
	"role" text NOT NULL,
	"active" integer DEFAULT 1 NOT NULL,
	"created_at" text NOT NULL
, "password_hash" text DEFAULT '' NOT NULL, "failed_logins" integer DEFAULT 0 NOT NULL, "locked_until" text);

CREATE TABLE "staff_sessions" (
	"token_hash" text PRIMARY KEY NOT NULL,
	"email" text NOT NULL,
	"created_at" text NOT NULL,
	"expires_at" text NOT NULL
);

CREATE INDEX "idx_notifications_order" ON "notifications" ("order_id");

CREATE INDEX "idx_notifications_status" ON "notifications" ("status");

CREATE INDEX "idx_order_events_order" ON "order_events" ("order_id");

CREATE INDEX "idx_orders_assignee" ON "orders" ("assignee");

CREATE INDEX "idx_orders_owner" ON "orders" ("owner");

CREATE INDEX "idx_orders_slot" ON "orders" ("slot");

CREATE INDEX "idx_orders_status" ON "orders" ("status");

CREATE INDEX "idx_payment_intents_expiry" ON "payment_intents" ("status","expires_at");

CREATE UNIQUE INDEX "idx_payment_intents_owner_request" ON "payment_intents" ("owner","request_key");

CREATE UNIQUE INDEX "idx_payment_intents_razorpay_order" ON "payment_intents" ("razorpay_order_id");

CREATE INDEX "idx_payment_stock_holds_intent" ON "payment_stock_holds" ("payment_intent_id","released_at");

CREATE INDEX "idx_staff_phone" ON "staff" ("phone");

CREATE INDEX "idx_staff_sessions_email" ON "staff_sessions" ("email");

CREATE UNIQUE INDEX "orders_request_key_unique" ON "orders" ("request_key");

